def transform(grid):
    n = len(grid)
    starts = [0, 5, 10, 15]

    # Read the repeated 4x4 pattern from a tile that contains 2s and no 3s.
    candidates = []
    for r0 in starts:
        for c0 in starts:
            tile = [row[c0:c0 + 4] for row in grid[r0:r0 + 4]]
            if any(2 in row for row in tile) and not any(3 in row for row in tile):
                candidates.append(tile)

    pattern = max(candidates, key=lambda t: sum(v == 2 for row in t for v in row))
    out = [[0 for _ in range(n)] for _ in range(n)]

    # The pattern recursively determines which tiles are present.
    for i, r0 in enumerate(starts):
        for j, c0 in enumerate(starts):
            if pattern[i][j] == 2:
                for a in range(4):
                    for b in range(4):
                        out[r0 + a][c0 + b] = pattern[a][b]
                out[r0 + i][c0 + j] = 8

    return out
